import * as React from "react";
import Layout from "../components/layout";
import { useTranslation } from "gatsby-plugin-react-i18next";
import { UserProfile } from "../interfaces";
import data from "../data/data.json";
import { graphql } from "gatsby";
import HeroBanner from "../components/heroBanner";
import images from "../images";
// import GalleryThumbnailsModal from "../components/galleryThumbnailsModal";

interface ServiceCardProps {
  title: string;
  copy: string;
  items: { item: string; itemElement?: string }[];
  content: string;
  index: number;
}

const WhyChooseUsItem: React.FC<{ item: string }> = ({ item }) => (
  <li className="flex items-start space-x-2">
    <span className="text-accent">✔</span>
    <p className="text-gray-700" dangerouslySetInnerHTML={{ __html: item }}></p>
  </li>
);

const ServiceCard: React.FC<ServiceCardProps> = ({
  title,
  copy,
  items,
  content,
  index,
}) => (
  <div className="bg-white p-6 rounded-lg shadow-md border border-gray-200">
    <h3 className="text-2xl font-semibold text-accent mb-4">{title}</h3>
    <p
      className="text-gray-700 mb-4"
      dangerouslySetInnerHTML={{ __html: copy }}
    ></p>
    {Array.isArray(items) &&
      items.length > 0 &&
      (index === 2 ? (
        <ol className="list-decimal pl-5 mb-4">
          {items.map((item, idx) => (
            <li
              key={idx}
              className="mb-2"
              dangerouslySetInnerHTML={{ __html: item.item }}
            ></li>
          ))}
        </ol>
      ) : (
        <ul className="list-disc pl-5 mb-4">
          {items.map((item, idx) => (
            <li key={idx} className="mb-2">
              {item.itemElement ? (
                <>
                  <strong>{item.item}:</strong>{" "}
                  <span
                    dangerouslySetInnerHTML={{ __html: item.itemElement }}
                  ></span>
                </>
              ) : (
                <span dangerouslySetInnerHTML={{ __html: item.item }}></span>
              )}
            </li>
          ))}
        </ul>
      ))}
    <p
      className="text-gray-600"
      dangerouslySetInnerHTML={{ __html: content }}
    ></p>
  </div>
);
const WhatWeDo: React.FC = () => {
  const { t } = useTranslation();
  const userData: UserProfile = data;
  const whyChooseUs =
  Object.values(t("whyChooseUs.items", { returnObjects: true })) || [];
  const services =
    Object.values(t("home.services", { returnObjects: true })) || [];

  return (
    <Layout data={userData}>

      <div className="w-full px-4">
        <HeroBanner backgroundImage={images.gallery_2.src} title="What we do">
          <p className="text-lg max-w-xl">
            Lorem ipsum dolor sit amet consectetur adipisicing elit. Quas quae explicabo provident fugit facilis enim dolores eos maxime totam debitis. Maxime, est. Veniam, nihil non debitis deserunt distinctio cupiditate eius!
          </p>
        </HeroBanner>
      </div>

      <div className={styles.container}>
        <article className={`${styles.section} w-full flex items-end mt-0`}>
          <div className="max-w-6xl mx-auto p-8">
            <h1 className={styles.title}>{t("home.slogan")}</h1>
            <p
              className="text-lg mt-4"
              dangerouslySetInnerHTML={{ __html: t("home.intro") || "" }}
            ></p>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mt-8">
              {services.length > 0 ? (
                services.map((service, index) => (
                  <ServiceCard key={index} index={index} {...service} />
                ))
              ) : (
                <p className="text-center col-span-3">No services available.</p>
              )}
            </div>
          </div>
        </article>

        {/* Sección de Galería */}
          {/* <article className={styles.section}>
            <GalleryThumbnailsModal />
          </article> */}

        {/* Sección Why Choose Us */}
          <article className={styles.section}>
            <div className="max-w-6xl mx-auto p-8">
              <h1 className={styles.title}>{t("whyChooseUs.title")}</h1>
              <ul className="list-none space-y-3 mt-4">
                {whyChooseUs.length > 0 ? (
                  whyChooseUs.map((item, index) => (
                    <WhyChooseUsItem key={index} item={item.item} />
                  ))
                ) : (
                  <p>No advantages listed.</p>
                )}
              </ul>
            </div>
          </article>
      </div>

    </Layout>
  );
};
export default WhatWeDo;

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  container: "flex flex-col justify-center items-center w-full ",
  // section: "bg-secondary-50 border-secondary flex mb-8 w-full border shadow-md",
  section: "flex mb-8 w-full shadow-md",
  title: "text-4xl text-accent",
  galleryWrapper: "flex flex-col justify-center items-center w-full",
};
